static void wypisz(File f, int glebokosc) {
    System.out.println("  ".repeat(glebokosc) + f.getName());
    if (f.isDirectory()) {
        for (File dziecko : f.listFiles()) {
            wypisz(dziecko, glebokosc + 1);
        }
    }
}

static void deleteDirectoryRecursively(File dir) {
    File[] dzieci = dir.listFiles();
    if (dzieci != null) {
        for (File d : dzieci) {
            deleteDirectoryRecursively(d);
        }
    }
    dir.delete();
}

