static final Map<Character, Character> MAPA = Map.of(
    'a', 'a', 'c', 'c', 'e', 'e', 'l', 'l', 'n', 'n', 'o', 'o', 's', 's', 'z', 'z');

static void renameSanitized(File dir) {
    for (File f : dir.listFiles()) {
        StringBuilder sb = new StringBuilder();
        for (char c : f.getName().toCharArray()) {
            if (c == ' ') sb.append('_');
            else sb.append(MAPA.getOrDefault(c, c));
        }
        f.renameTo(new File(dir, sb.toString()));
    }
}

static void usunPusteKatalogi(File dir) {
    for (File f : dir.listFiles()) {
        if (f.isDirectory()) {
            usunPusteKatalogi(f);
            if (f.listFiles().length == 0) {
                f.delete();
            }
        }
    }
}

static void porownaj(Map<String, Long> przed, Map<String, Long> po) {
    for (String sciezka : po.keySet()) {
        if (!przed.containsKey(sciezka)) {
            System.out.println("DODANO: " + sciezka);
        } else if (!przed.get(sciezka).equals(po.get(sciezka))) {
            System.out.println("ZMODYFIKOWANO: " + sciezka);
        }
    }
    for (String sciezka : przed.keySet()) {
        if (!po.containsKey(sciezka)) {
            System.out.println("USUNIETO: " + sciezka);
        }
    }
}
